arguments.command:
cd /tmp/t/b && make -j4 >/dev/null 2>&1; make install >/dev/null 2>&1; /tmp/inst/bin/isodur --version; /tmp/inst/bin/durfmt --help 2>&1 | head -3; cat > /tmp/a.c <<'E'
#include <isodur/isodur.h>
#include <stdio.h>
int main(){puts(isodur_version());return 0;}
E
export PKG_CONFIG_PATH=/tmp/inst/lib/pkgconfig; cc /tmp/a.c -o /tmp/a $(pkg-config --cflags --libs isodur) -Wl,-rpath,/tmp/inst/lib && /tmp/a; nm -D /tmp/inst/lib/libisodur.so | grep " T "; readelf -d /tmp/inst/lib/libisodur.so | grep -E "NEEDED|SONAME"

